def int_to_roman(number):
    num_dict = {
        1: 'I', 4: 'IV', 5: 'V', 9: 'IX',
        10: 'X', 40: 'XL', 50: 'L', 90: 'XC',
        100: 'C', 400: 'CD', 500: 'D', 900: 'CM',
        1000: 'M'
    }

    roman_numeral = ''
    for values in sorted(num_dict.items(), reverse=True):
        while number >= values[0]:
            roman_numeral += values[1]
            number -= values[0]

    return roman_numeral

import re
def extract_quotation(string):
    return re.findall(r'"([^"]*)"', string)

import re
def camel_to_snake(camel_case_string):
    snake_case_string = re.sub('(.)([A-Z][a-z]+)', r'\1_\2', camel_case_string)
    return re.sub('([a-z0-9])([A-Z])', r'\1_\2', snake_case_string).lower()

def sum_Of_Primes(n):
    import math
    import math

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    prime_numbers = [num for num in range(2, n + 1) if is_prime(num)]
    return sum(prime_numbers)

import heapq
def combine_lists(list1, list2):
    return list(heapq.merge(list1, list2))

def even_position(my_list):
    for i in range(0, len(my_list), 2):
        if my_list[i] % 2 != 0:
            return False
    return True

def equilibrium_index(arr):
    left_sum = sum(arr[:len(arr)//2])
    right_sum = sum(arr[len(arr)//2+1:])
    if left_sum == right_sum:
        return len(arr)//2
    return -1
